sealZeroPad:
	CMPQ R9, CX
	JAE  sealZeroPadDone
	MOVB $0x00, 256(BP)(R9*1)
	INCQ R9
	JMP  sealZeroPad

sealZeroPadDone:
	// Seal hashes the ciphertext it just produced
	MOVQ BX, CX
	XORQ R9, R9

sealHashLoop:
	TESTQ CX, CX
	JLE   sealHashDone
	ADDQ  256(BP)(R9*1), R10
	ADCQ  264(BP)(R9*1), R11
	ADCQ  $0x01, R12
	MOVQ  (BP), DX
