	VMOVDQU32 Z1, 448(BP)
	MOVQ      BX, CX
	XORQ      R9, R9

openOutCopy8:
	CMPQ CX, $0x08
	JB   openOutCopy1
	MOVQ 256(BP)(R9*1), R13
	MOVQ R13, (DI)(R9*1)
	ADDQ $0x08, R9
	SUBQ $0x08, CX
	JMP  openOutCopy8

openOutCopy1:
	TESTQ CX, CX
	JZ    openOutCopyDone
	MOVB  256(BP)(R9*1), R13
	MOVB  R13, (DI)(R9*1)
	INCQ  R9
	DECQ  CX
	JMP   openOutCopy1

openOutCopyDone:
	// Advance the output cursor so the tag, or the tag compare, lands correctly
	ADDQ BX, DI
	ADDQ BX, SI

openAVX512Finalize:
	// Hash in the buffer lengths
	ADDQ  ad_len+80(FP), R10
	ADCQ  src_len+56(FP), R11
	ADCQ  $0x01, R12
	MOVQ  (BP), AX
	MOVQ  AX, R15
	MULQ  R10
	MOVQ  AX, R13
	MOVQ  DX, R14
	MOVQ  (BP), AX
	MULQ  R11
	IMULQ R12, R15
	ADDQ  AX, R14
	ADCQ  DX, R15
	MOVQ  8(BP), AX
	MOVQ  AX, R8
	MULQ  R10
	ADDQ  AX, R14
	ADCQ  $0x00, DX
	MOVQ  DX, R10
	MOVQ  8(BP), AX
	MULQ  R11
	ADDQ  AX, R15
	ADCQ  $0x00, DX
	IMULQ R12, R8
	ADDQ  R10, R15
	ADCQ  DX, R8
	MOVQ  R13, R10
	MOVQ  R14, R11
	MOVQ  R15, R12
	ANDQ  $0x03, R12
	MOVQ  R15, R13
	ANDQ  $-4, R13
	MOVQ  R8, R14
	SHRQ  $0x02, R8, R15
	SHRQ  $0x02, R8
	ADDQ  R13, R10
	ADCQ  R14, R11
	ADCQ  $0x00, R12
	ADDQ  R15, R10
	ADCQ  R8, R11
	ADCQ  $0x00, R12

	// Final reduce
	MOVQ    R10, R13
	MOVQ    R11, R14
	MOVQ    R12, R15
	SUBQ    $-5, R10
	SBBQ    $-1, R11
	SBBQ    $0x03, R12
	CMOVQCS R13, R10
	CMOVQCS R14, R11
	CMOVQCS R15, R12

	// Add in the "s" part of the key
	ADDQ 16(BP), R10
	ADCQ 24(BP), R11

	// Constant time compare against the tag, which sits just past the ciphertext
	XORQ    AX, AX
	MOVQ    $0x00000001, DX
	XORQ    (SI), R10
	XORQ    8(SI), R11
	ORQ     R11, R10
	CMOVQEQ DX, AX

	// Return true iff the tags are equal
	VZEROUPPER
	MOVB AX, ret+96(FP)
	RET
